function testSumColumn() {
  const values = [["Crop", "Kilograms"], ["Kale", 2.2], ["Kale", "0.6"], ["Mint", 3.6]]
  console.log(sumColumn(values, 1))
}

function sumColumn(values, columnIndex) {
  let total = 0
  for (let i = 1; i < values.length; i++) {
    total = total + Number(values[i][columnIndex])
  }
  return Math.round(total * 10) / 10
}
